/**
 * The week-so-far feed v1 (src/feed-v3.ts) against the two references it must equal:
 *  1. the kit's FEED CONTRACT: the example feed agents/kit/test/vectors/week-so-far.v1.json (generated by the kit's
 *     supersetFeed from a recorded window) is rebuilt from its raw part to the byte; when the kit's dependencies are
 *     installed (agents/kit/node_modules), the kit's own supersetFeed and feedProblems are run on every feed built here;
 *  2. the epoch build: on the same inputs, computeEpochV3 (the weekly build) records exactly the feed's capacity, XNT
 *     prices, chain L, cap, reference spot and curve state, on every golden world of the kit's vectors and on the
 *     recorded epoch-2 sources of test/fixtures (the build's own reader, assembleInputsV3).
 * No network.
 */
import assert from "assert";
import * as fs from "fs";
import * as path from "path";
import { pathToFileURL } from "url";
import { CHAINS, ChainConfig } from "../src/config";
import { EpochFile } from "../src/epoch";
import {
  assembleWeekSoFarV3, buildWeekSoFarV1, checkRawV1, engineSha256Of, FEED_PROVISIONAL, feedGateV3, feedInputsV3, feedText, knownReadingsOfFeedV1, rawOfFeedV1,
  WeekSoFarFeedV1, WeekSoFarRawV1, weekSoFarFeedV1, samplesOfFeedV1,
} from "../src/feed-v3";
import { assembleInputsV3, buildV3, fixtureSources, RecordedSourcesV3, SourcesV3 } from "../src/flow-v3";
import { AnyEpochFile, computeEpochV3, EpochBodyV3, EpochInputsV3, globalOrder, HOUR, verifyAny, windowStateV3 } from "../src/rewards";
import { feedVerdict } from "../src/health-rules";

let passed = 0;
let failed = 0;
let skippedTests = 0;
async function test(name: string, fn: () => void | Promise<void>) {
  try {
    await fn();
    passed++;
  } catch (e) {
    failed++;
    console.error(`FAIL ${name}\n  ${(e as Error).stack ?? String(e)}`);
  }
}

const REPO = path.join(__dirname, "..", "..");
const KIT = path.join(REPO, "agents", "kit");
const FIX = path.join(__dirname, "fixtures");
const FEED_FIXTURE = path.join(KIT, "test", "vectors", "week-so-far.v1.json");
const VECTORS = path.join(KIT, "test", "vectors", "quote-v3.json");
/**
 * The kit's recorded vectors ship with the kit's v3 files. A tree without them (main before that release) skips the tests
 * that read them and counts them as skipped; every other test here still runs.
 */
const KIT_VECTORS = fs.existsSync(FEED_FIXTURE) && fs.existsSync(VECTORS);
let skippedNoVectors = 0;
/** a test that reads the kit's recorded vectors */
async function vtest(name: string, fn: () => void | Promise<void>) {
  if (!KIT_VECTORS) {
    skippedNoVectors++;
    return;
  }
  await test(name, fn);
}
const epoch1: EpochFile = JSON.parse(fs.readFileSync(path.join(FIX, "epoch-1.json"), "utf8"));
const flowFixture: { recording: RecordedSourcesV3 } = JSON.parse(fs.readFileSync(path.join(FIX, "flow-v3-epoch2.json"), "utf8"));
const rec = (): RecordedSourcesV3 => JSON.parse(JSON.stringify(flowFixture.recording));
const PORTAL = epoch1.chains[0].portal;
const chains: ChainConfig[] = CHAINS.map((c) => ({ ...c, portal: epoch1.chains.some((x) => x.chainId === c.chainId) ? PORTAL : "" }));
const quiet = () => {};
const clone = <T>(v: T): T => JSON.parse(JSON.stringify(v));

/** ts-node compiles import() to require(); the kit is ES modules, so the native import is kept out of its reach */
const importEsm = new Function("u", "return import(u)") as (u: string) => Promise<any>;
interface Kit {
  supersetFeed(feed: unknown, prev: unknown): any;
  feedProblems(feed: unknown, o: { now: number }): string[];
  /** the kit's engine (quote-v3.mjs) mirrors D-13 (the frozen L) and D-22 (the tranche cap, the peg guard) */
  mirrorsD13: boolean;
}

let kitSeniorDiffs = 0;
/**
 * The kit's supersetFeed of a feed, compared with the oracle's. D-13 (the window's L frozen at epoch n−1's build) and
 * D-22 (a, c) move one derived number of the feed, Σ senior (and C when the XDEX cap binds): until the kit's engine mirrors
 * them (it then exports liquidityRuleV3), those two are taken from the engine and every other field must still be equal.
 */
function kitView(kit: Kit, kitFeed: any, feed: WeekSoFarFeedV1): any {
  if (kit.mirrorsD13 || !kitFeed?.capacity) return kitFeed;
  if (kitFeed.capacity.senior !== feed.capacity.senior) kitSeniorDiffs++;
  return { ...kitFeed, capacity: { ...kitFeed.capacity, cash: feed.capacity.cash, senior: feed.capacity.senior } };
}
async function loadKit(): Promise<Kit | null> {
  if (!fs.existsSync(path.join(KIT, "node_modules", "@solana", "web3.js"))) return null;
  try {
    const gen = await importEsm(pathToFileURL(path.join(KIT, "test", "vectors", "gen-week-so-far.mjs")).href);
    const burn = await importEsm(pathToFileURL(path.join(KIT, "burn.mjs")).href);
    const quote = await importEsm(pathToFileURL(path.join(KIT, "quote-v3.mjs")).href);
    return { supersetFeed: gen.supersetFeed, feedProblems: burn.feedProblems, mirrorsD13: typeof quote.liquidityRuleV3 === "function" };
  } catch (e) {
    console.log(`  (the kit could not be loaded: ${String((e as Error).message).slice(0, 160)})`);
    return null;
  }
}

/** a golden world's previous file (kit test/unit/helpers-v3.mjs prevOf) */
function prevOfWorld(v: any, w: any): AnyEpochFile | null {
  if (w.prev === null) return null;
  if (w.prev === "epoch-1") return epoch1;
  return v.prevFiles[w.prev];
}

/** the feed's raw part for a golden world at `now` (the kit's feedFromWorld): the burns before now, one burn's readings as the hour's */
function rawOfWorld(w: any, prev: AnyEpochFile, now: number): WeekSoFarRawV1 {
  const inputs = w.inputs as EpochInputsV3;
  const hour = Math.floor(now / HOUR);
  const all = inputs.chains.flatMap((c) => c.burns).sort(globalOrder);
  const any = all.find((b) => b.priceSource === "candles" && b.xntSource === "candles") ?? all[0];
  const r = any && any.priceSource === "candles" ? { m: any.medianE18, l: any.lastCloseE18, s: "candles" as const } : { m: "0", l: "0", s: "fallback" as const };
  const x = any && any.xntSource === "candles" ? { m: any.xntMedianE18, l: any.xntLastCloseE18, s: "candles" as const } : { m: "0", l: "0", s: "fallback" as const };
  return {
    kind: "week-so-far", version: 1, programId: inputs.programId, rules: 3, epoch: inputs.epoch, asOf: now,
    prevEpoch: { epoch: prev.epoch, dataHash: prev.dataHash }, window: { startTs: inputs.window.startTs },
    freePool: { open: inputs.freePool.open ?? inputs.freePool.lamports, now: inputs.freePool.lamports },
    xnt: { twapE18: inputs.xnt.twapE18, apiE18: inputs.xnt.apiE18, current: { hour, medianE18: x.m, lastCloseE18: x.l, source: x.s } },
    chains: inputs.chains.map((c) => ({
      chainId: c.chainId, name: c.name, portal: c.portal, status: "ok" as const, market: c.market, liquidityNowMicro: c.liquidityNowMicro,
      burns: c.burns.filter((b) => b.timestamp < now), current: { hour, medianE18: r.m, lastCloseE18: r.l, priceSource: r.s },
    })),
    switchRefs: inputs.switchRefs ?? null,
  };
}

/** what the epoch build records, field by field, is what the feed says (same inputs, same engine) */
function assertFeedIsBuild(feed: WeekSoFarFeedV1, body: EpochBodyV3, what: string) {
  assert.strictEqual(feed.capacity.cash, body.capacity.cash, `${what}: capacity.cash = the build's C`);
  if (body.capacity.shortfall === null) assert.strictEqual(feed.capacity.senior, body.capacity.senior, `${what}: Σ senior = the build's`);
  assert.strictEqual(feed.xnt.buildE18, body.xnt.buildE18, `${what}: XNT build price`);
  assert.strictEqual(feed.xnt.floorE18, body.xnt.floorE18, `${what}: XNT floor`);
  assert.strictEqual(feed.window.startTs, body.window.startTs, `${what}: window start`);
  assert.strictEqual(feed.prevDataHash, body.prevDataHash, `${what}: previous data hash`);
  for (const c of feed.chains) {
    const b = body.chains.find((x) => x.chainId === c.chainId)!;
    if (c.status === "skipped") {
      assert(!b || b.skipped, `${what}: chain ${c.chainId} skipped in both`);
      continue;
    }
    assert(b && !b.skipped, `${what}: chain ${c.chainId} valued in both`);
    assert.strictEqual(c.Lnow, b.L.now, `${what}: chain ${c.chainId} Lnow = L.now`);
    assert.strictEqual(c.Lprev, b.L.prev, `${what}: chain ${c.chainId} Lprev = L.prev`);
    assert.strictEqual(c.capE18, b.priceCapE18, `${what}: chain ${c.chainId} cap`);
    assert.strictEqual(c.spotE18, b.xenUsdE18, `${what}: chain ${c.chainId} reference spot`);
    const mine = body.burns.filter((x) => x.chainId === c.chainId);
    if (!mine.length) {
      assert.deepStrictEqual([c.S, c.hour, c.hourSpot], [b.curveBefore.S, b.curveBefore.hour, "0"], `${what}: chain ${c.chainId} curve with no burn`);
    } else {
      const last = Math.max(...mine.map((x) => x.hour));
      const V = mine.filter((x) => x.hour === last).reduce((s, x) => s + BigInt(x.spotMicro), 0n);
      assert.strictEqual(c.hourSpot, V.toString(), `${what}: chain ${c.chainId} the latest hour's spot`);
      assert.strictEqual((BigInt(c.S!) + V).toString(), b.curveAfter.S, `${what}: chain ${c.chainId} S + hourSpot = curveAfter.S`);
      assert.strictEqual(c.hour, b.curveAfter.hour, `${what}: chain ${c.chainId} curve hour`);
    }
    // the raw burns are exactly the build's recorded inputs
    const rawBurns = (c.burns ?? []).slice().sort(globalOrder);
    const keys = ["chainId", "txHash", "logIndex", "blockNumber", "missionId", "pilot", "amountWei", "tier", "x1", "timestamp", "medianE18", "lastCloseE18", "priceSource", "xntMedianE18", "xntLastCloseE18", "xntSource"] as const;
    assert.deepStrictEqual(
      rawBurns.map((x) => keys.map((k) => (x as any)[k])),
      mine.map((x) => keys.map((k) => (x as any)[k])),
      `${what}: chain ${c.chainId} burns are the build's`,
    );
  }
}

async function main() {
  const kit = await loadKit();
  if (!kit) console.log("  (agents/kit/node_modules is not installed: the kit's own supersetFeed/feedProblems checks are skipped; the recorded example still runs)");
  if (!KIT_VECTORS) console.log("  (agents/kit/test/vectors is not in this tree: the tests that read the kit's recorded vectors are skipped)");
  const fixture = KIT_VECTORS ? JSON.parse(fs.readFileSync(FEED_FIXTURE, "utf8")) : null;

  // ── 1. the kit's recorded window ─────────────────────────────────────────────────────────────────
  await vtest("FEED CONTRACT: the kit's example feed (week-so-far.v1.json) is rebuilt from its raw part, to the byte", () => {
    assert.strictEqual(fixture.prevRef.prev, "epoch-1", "the example continues the real epoch-1.json");
    const raw = rawOfFeedV1(fixture.feed);
    const feed = weekSoFarFeedV1(raw, epoch1);
    assert.deepStrictEqual(feed, fixture.feed);
    assert.strictEqual(JSON.stringify(feed), JSON.stringify(fixture.feed), "same fields in the same order");
    assert.strictEqual(feedText(feed), JSON.stringify(fixture.feed) + "\n");
  });

  await vtest("the example's numbers are the epoch build's on the same inputs (computeEpochV3, provisional window)", () => {
    const raw = rawOfFeedV1(fixture.feed);
    const body = computeEpochV3(feedInputsV3(raw, epoch1), epoch1, { provisional: FEED_PROVISIONAL });
    assert(body, "the example's window pays somebody");
    assertFeedIsBuild(fixture.feed, body!, "example");
  });

  // ── 2. every golden world, at several hours ───────────────────────────────────────────────────────
  await vtest("every golden world with a previous file, after each burn's hour: feed = epoch build (and = the kit's supersetFeed)", async () => {
    const v = JSON.parse(fs.readFileSync(VECTORS, "utf8"));
    let feeds = 0;
    let compared = 0;
    let kitChecked = 0;
    let unpricedSeen = 0;
    for (const w of v.worlds) {
      const prev = prevOfWorld(v, w);
      if (!prev) continue;
      const hours = [...new Set(w.inputs.chains.flatMap((c: any) => c.burns).map((b: any) => Math.floor(b.timestamp / HOUR)))] as number[];
      const times = [w.inputs.window.startTs + 60, ...hours.sort((a, b) => a - b).slice(0, 6).map((h) => (h + 1) * HOUR + 600)].filter((t) => t <= w.inputs.window.endTs);
      for (const now of times) {
        const raw = rawOfWorld(w, prev, now);
        let built: ReturnType<typeof buildWeekSoFarV1>;
        try {
          built = buildWeekSoFarV1(raw, prev);
        } catch (e) {
          // the engine refuses these inputs: so does the build
          assert.throws(() => computeEpochV3(feedInputsV3(raw, prev), prev, { provisional: FEED_PROVISIONAL }), Error, `${w.name} at ${now}: ${(e as Error).message}`);
          continue;
        }
        const { feed, unpriced } = built;
        feeds++;
        if (unpriced.length) unpricedSeen++;
        // the raw part as valued (unpriced chains marked skipped) gives back the same feed
        assert.deepStrictEqual(weekSoFarFeedV1(rawOfFeedV1(feed), prev), feed, `${w.name} at ${now}: idempotent`);
        const valued = rawOfFeedV1(feed);
        const body = computeEpochV3(feedInputsV3(valued, prev), prev, { provisional: FEED_PROVISIONAL });
        if (body) {
          assertFeedIsBuild(feed, body, `${w.name} at ${now}`);
          compared++;
        } else {
          // nothing paid yet: the build publishes nothing, the feed still states the week (the engine's own state)
          const st = windowStateV3(feedInputsV3(valued, prev), prev, { limit: true, provisional: FEED_PROVISIONAL });
          assert.strictEqual(feed.capacity.cash, st.C.toString());
          assert.strictEqual(feed.capacity.senior, st.alloc.senior.toString());
        }
        if (kit) {
          assert.deepStrictEqual(kitView(kit, kit.supersetFeed(rawOfFeedV1(feed), prev), feed), feed, `${w.name} at ${now}: = the kit's supersetFeed`);
          assert.deepStrictEqual(kit.feedProblems(feed, { now }), [], `${w.name} at ${now}: the kit accepts the feed`);
          kitChecked++;
        }
      }
    }
    assert(feeds > 40, `enough feeds built (${feeds})`);
    assert(compared > 30, `enough compared with a build (${compared})`);
    console.log(`  golden worlds: ${feeds} feeds, ${compared} equal to the epoch build, ${kitChecked} equal to the kit's supersetFeed, ${unpricedSeen} with an unpriced chain`);
    if (kit && !kit.mirrorsD13) console.log(`  MIRROR PENDING: the kit's engine does not implement D-13 / D-22 yet: ${kitSeniorDiffs} of ${kitChecked} feeds differ in capacity.senior only (taken from the engine)`);
  });

  await vtest("a shortfall world: the feed quotes the plain FCFS run at C (the kit's), the build may cut it", () => {
    const v = JSON.parse(fs.readFileSync(VECTORS, "utf8"));
    const w = v.worlds.find((x: any) => x.expected?.shortfall && x.prev !== null);
    assert(w, "the vectors have a shortfall world with a previous file");
    const prev = prevOfWorld(v, w)!;
    const raw = rawOfWorld(w, prev, w.inputs.window.endTs);
    const feed = weekSoFarFeedV1(raw, prev);
    const noLimit = windowStateV3(feedInputsV3(raw, prev), prev, { limit: false, provisional: FEED_PROVISIONAL });
    const withLimit = windowStateV3(feedInputsV3(raw, prev), prev, { limit: true, provisional: FEED_PROVISIONAL });
    assert.strictEqual(feed.capacity.senior, noLimit.alloc.senior.toString());
    assert(withLimit.alloc.cut !== null, "the build limit cuts this window");
    assert(noLimit.alloc.senior >= withLimit.alloc.senior, "the cut only lowers what is paid");
  });

  // ── 3. refusals and the dormant gate ──────────────────────────────────────────────────────────────
  await vtest("the raw part is refused when it does not continue epoch n−1, is not v3, or carries another hour's readings", () => {
    const raw = rawOfFeedV1(fixture.feed);
    assert.doesNotThrow(() => checkRawV1(raw, epoch1));
    assert.throws(() => checkRawV1({ ...raw, rules: 2 as unknown as 3 }, epoch1), /only under the v3 rules/);
    assert.throws(() => checkRawV1({ ...raw, prevEpoch: { epoch: 1, dataHash: "00".repeat(32) } }, epoch1), /does not continue/);
    assert.throws(() => checkRawV1({ ...raw, epoch: 3 }, epoch1), /previous file is epoch 1/);
    assert.throws(() => checkRawV1(raw, null), /epoch n−1's file is required/);
    const late = clone(raw);
    late.asOf += HOUR;
    assert.throws(() => checkRawV1(late, epoch1), /not the feed's hour/);
    const twice = clone(raw);
    twice.chains.push(clone(twice.chains[0]));
    assert.throws(() => checkRawV1(twice, epoch1), /twice/);
  });

  await test("dormant until the switch: no feed under the v2 rules or on a binary that is not the upgraded one", () => {
    assert.strictEqual(feedGateV3({ rewardsVersion: 2, upgrade: "upgraded" }).active, false);
    assert.strictEqual(feedGateV3({ rewardsVersion: 3, upgrade: "legacy" }).active, false);
    assert.strictEqual(feedGateV3({ rewardsVersion: 3, upgrade: "unknown", reasons: ["rpc"] }).active, false);
    assert.match(feedGateV3({ rewardsVersion: 3, upgrade: "unknown", reasons: ["rpc"] }).reason, /not the upgraded binary \(unknown: rpc\)/);
    assert.deepStrictEqual(feedGateV3({ rewardsVersion: 3, upgrade: "upgraded" }), { active: true, reason: "" });
  });

  await vtest("a chain with a burn that has no XEN price is skipped, as the build skips it", () => {
    const raw = rawOfFeedV1(fixture.feed);
    const bad = clone(raw);
    const c = bad.chains.find((x) => x.status === "ok" && (x.burns ?? []).length)!;
    c.market = { ...c.market!, spotE18: "0" };
    for (const b of c.burns!) Object.assign(b, { medianE18: "0", lastCloseE18: "0", priceSource: "fallback" });
    const { feed, unpriced } = buildWeekSoFarV1(bad, epoch1);
    assert.deepStrictEqual(unpriced, [c.chainId]);
    assert(feed.skipped.includes(c.chainId));
    assert.deepStrictEqual(feed.chains.find((x) => x.chainId === c.chainId), { chainId: c.chainId, name: c.name, portal: c.portal, status: "skipped" });
    const built = buildV3(feedInputsV3(bad, epoch1), epoch1, { provisional: FEED_PROVISIONAL });
    assert.deepStrictEqual(built.unpriced, [c.chainId], "the build skips the same chain");
    if (kit) assert.deepStrictEqual(kitView(kit, kit.supersetFeed(rawOfFeedV1(feed), epoch1), feed), feed);
  });

  // ── 4. the live writer's assembly, on the recorded epoch-2 sources ────────────────────────────────
  const counted = (r: RecordedSourcesV3, calls: string[], o: Partial<SourcesV3> = {}): SourcesV3 => {
    const s = { ...fixtureSources(r), ...o };
    return {
      ...s,
      xenCloses: (c, m, h) => (calls.push(`xen:${c.chainId}:${h}`), s.xenCloses(c, m, h)),
      xntCloses: (h) => (calls.push(`xnt:${h}`), s.xntCloses(h)),
    };
  };
  const calls1: string[] = [];
  const a1 = await assembleWeekSoFarV3(epoch1, counted(rec(), calls1), chains, [epoch1], quiet, { engineSha256: engineSha256Of() });
  const base = await assembleInputsV3(2, epoch1, fixtureSources(rec()), chains, [epoch1], quiet);
  const built = buildV3(base.inputs, epoch1).file!;

  await test("the writer reads the window with the build's reader: same window, cursors, markets, liquidity and burns", () => {
    const f = a1.feed;
    assert.deepStrictEqual(a1.skipped, []);
    assert.strictEqual(f.kind, "week-so-far");
    assert.strictEqual(f.version, 1);
    assert.strictEqual(f.rules, 3);
    assert.strictEqual(f.epoch, 2);
    assert.strictEqual(f.programId, base.inputs.programId);
    assert.strictEqual(f.asOf, base.inputs.window.endTs, "asOf = the finalized X1 slot's block time");
    assert.deepStrictEqual(f.window, { startTs: base.inputs.window.startTs });
    assert.deepStrictEqual(f.freePool, { open: base.inputs.freePool.open, now: base.inputs.freePool.lamports });
    assert.deepStrictEqual(f.prevEpoch, { epoch: 1, dataHash: epoch1.dataHash });
    assert.deepStrictEqual(f.switchRefs, base.inputs.switchRefs, "the switch epoch's reference history");
    assert.strictEqual(f.engineSha256, engineSha256Of());
    assert.match(f.engineSha256!, /^[0-9a-f]{64}$/);
    for (const ci of base.inputs.chains) {
      const c = f.chains.find((x) => x.chainId === ci.chainId)!;
      assert.strictEqual(c.status, "ok");
      assert.deepStrictEqual([c.fromBlockExclusive, c.toBlock], [ci.fromBlockExclusive, ci.toBlock]);
      assert.deepStrictEqual(c.market, ci.market);
      assert.strictEqual(c.liquidityNowMicro, ci.liquidityNowMicro);
      assert.deepStrictEqual(c.burns, ci.burns);
    }
    assert.strictEqual(f.readings.hour, Math.floor(f.asOf / HOUR));
  });

  await test("the writer's numbers are the epoch build's on the recorded sources (the weekly build's own inputs)", () => {
    assert.strictEqual(built.capacity.shortfall, null);
    assertFeedIsBuild(a1.feed, built, "recorded epoch 2");
    assert.deepStrictEqual(weekSoFarFeedV1(rawOfFeedV1(a1.feed), epoch1), a1.feed, "the published feed rebuilds from its raw part");
  });

  await test("the kit accepts the writer's feed (feedProblems) and re-derives it to the field (supersetFeed)", () => {
    if (!kit) {
      skippedTests++;
      return;
    }
    assert.deepStrictEqual(kit.feedProblems(a1.feed, { now: a1.feed.asOf + 60 }), []);
    assert.deepStrictEqual(kitView(kit, kit.supersetFeed(rawOfFeedV1(a1.feed), epoch1), a1.feed), a1.feed);
  });

  await test("the current hour: no candle is 'fallback' (as the build records it); a read that fails leaves `current` out", async () => {
    // the recording has no candle for the current hour: every chain is 'fallback', null in readings
    for (const c of a1.feed.chains.filter((x) => x.status === "ok")) {
      assert.deepStrictEqual(c.current, { hour: a1.feed.readings.hour, medianE18: "0", lastCloseE18: "0", priceSource: "fallback" });
      assert.strictEqual(a1.feed.readings.xen[String(c.chainId)], null);
    }
    const hourStart = Math.floor(a1.feed.asOf / HOUR) * HOUR;
    const failing = await assembleWeekSoFarV3(epoch1, { ...fixtureSources(rec()), xenCloses: async (c, m, h) => { if (h === hourStart) throw new Error("429"); return fixtureSources(rec()).xenCloses(c, m, h); } }, chains, [epoch1], quiet);
    for (const c of failing.feed.chains.filter((x) => x.status === "ok")) assert(!("current" in c), `chain ${c.chainId}: no readings this hour, so no quote`);
    assert.deepStrictEqual(failing.feed.readings.xen, {});
    assert.deepStrictEqual(failing.feed.capacity, a1.feed.capacity, "the readings of the hour never move the window's numbers");
  });

  await test("the previous hour's feed spares the candles already read; another window's feed is never used", async () => {
    const id = { programId: a1.feed.programId, epoch: 2, prevDataHash: epoch1.dataHash };
    assert.strictEqual(knownReadingsOfFeedV1({ ...a1.feed, epoch: 3 }, id), null);
    assert.strictEqual(knownReadingsOfFeedV1({ ...a1.feed, prevEpoch: { epoch: 1, dataHash: "ff".repeat(32) } }, id), null);
    assert.strictEqual(knownReadingsOfFeedV1({ ...a1.feed, version: 2 }, id), null);
    assert.strictEqual(knownReadingsOfFeedV1(null, id), null);
    const known = knownReadingsOfFeedV1(a1.feed, id)!;
    const candleBurns = a1.feed.chains.flatMap((c) => c.burns ?? []).filter((b) => b.priceSource === "candles");
    assert(candleBurns.length > 0);
    for (const b of candleBurns) {
      const h = Math.floor(b.timestamp / HOUR) * HOUR;
      assert.deepStrictEqual(known.xen(b.chainId, h), { medianE18: b.medianE18, lastCloseE18: b.lastCloseE18, source: "candles" });
    }
    const fallbackBurns = a1.feed.chains.flatMap((c) => c.burns ?? []).filter((b) => b.priceSource === "fallback");
    for (const b of fallbackBurns) assert.strictEqual(known.xen(b.chainId, Math.floor(b.timestamp / HOUR) * HOUR), null, "a fallback hour is read again");
    const calls2: string[] = [];
    const a2 = await assembleWeekSoFarV3(epoch1, counted(rec(), calls2), chains, [epoch1], quiet, { known, engineSha256: engineSha256Of() });
    assert.deepStrictEqual(a2.feed, a1.feed, "the same feed");
    for (const b of candleBurns) assert(!calls2.includes(`xen:${b.chainId}:${Math.floor(b.timestamp / HOUR) * HOUR}`), "a known hour is not read again");
    assert(calls2.length < calls1.length, `fewer candle reads (${calls2.length} < ${calls1.length})`);
  });

  await test("D-13 / route / xdex / flags: each hour appends its reading to the window's samples; the build records them; the kit gets its route", async () => {
    const id = { programId: a1.feed.programId, epoch: 2, prevDataHash: epoch1.dataHash };
    const xdex = { pool: "CAJeVEoSm1QQZccnCqYu9cnNF7TTD2fcUA3E5HQoxRvR", slot: 5, wxntReserveLamports: "18000000000000", usdcReserveMicro: "4900000000", feedBps: 0, feeBps: 28 } as any;
    delete xdex.feedBps;
    const route = (c: ChainConfig) => ({ pool: `0x${"11".repeat(20)}`, xenReserveWei: `${c.chainId}000000000000000000000`, quoteReserveMicro: "1000000000", feeBps: 30, bridgeFeeMicro: "1000000", bridgeMinMicro: "10000000" });
    const withDepth = (onChain: (c: ChainConfig) => string | null): SourcesV3 => ({
      ...fixtureSources(rec()),
      depth: async (c) => ({ micro: onChain(c), route: route(c) }),
      xdex: async () => xdex,
    });
    // hour 1: no previous feed: one sample per valued chain, min(GeckoTerminal, on-chain)
    const h1 = await assembleWeekSoFarV3(epoch1, withDepth(() => "5"), chains, [epoch1], quiet, { anomalyHold: true });
    const hour = Math.floor(h1.feed.asOf / HOUR);
    for (const c of h1.feed.chains.filter((x) => x.status === "ok")) {
      assert.deepStrictEqual(c.liquiditySamples, [{ hour, micro: "5" }], `chain ${c.chainId}: this hour's reading is min(GeckoTerminal, on-chain)`);
      assert.strictEqual(c.liquidityOnChainMicro, "5");
      assert.deepStrictEqual(c.route, route(chains.find((x) => x.chainId === c.chainId)!));
    }
    assert.deepStrictEqual(h1.feed.xdex, xdex);
    assert.deepStrictEqual(h1.feed.flags, { anomalyHold: true });
    // hour 2 (an earlier hour's feed carried): the samples accumulate, another window's samples are never taken
    const prevSamples = new Map(h1.feed.chains.filter((c) => c.status === "ok").map((c) => [c.chainId, [{ hour: hour - 3, micro: "7" }, ...(c.liquiditySamples ?? [])].map((s) => ({ ...s, hour: s.hour - 1 }))]));
    const fake = { ...h1.feed, chains: h1.feed.chains.map((c) => (c.status === "ok" ? { ...c, liquiditySamples: prevSamples.get(c.chainId) } : c)) };
    const got = samplesOfFeedV1(fake, id);
    assert.deepStrictEqual(got.get(10), prevSamples.get(10));
    assert.strictEqual(samplesOfFeedV1({ ...fake, epoch: 3 }, id).size, 0, "another window's feed gives no sample");
    assert.strictEqual(samplesOfFeedV1({ ...fake, prevEpoch: { epoch: 1, dataHash: "ee".repeat(32) } }, id).size, 0);
    const h2 = await assembleWeekSoFarV3(epoch1, withDepth(() => null), chains, [epoch1], quiet, { samples: got });
    for (const c of h2.feed.chains.filter((x) => x.status === "ok")) {
      const lnow = c.liquidityNowMicro!;
      assert.deepStrictEqual(c.liquiditySamples, [...prevSamples.get(c.chainId)!, { hour, micro: lnow }], `chain ${c.chainId}: the earlier samples, then this hour's (on-chain unread: GeckoTerminal alone)`);
    }
    assert.deepStrictEqual(h2.feed.flags, { anomalyHold: false });
    // the build of the same window records the feed's samples (and its own reading as the end hour's) and the XDEX reading
    const b = await assembleInputsV3(2, epoch1, withDepth(() => "5"), chains, [epoch1], quiet, { samples: (cid) => got.get(cid) ?? null });
    const f = buildV3(b.inputs, epoch1).file!;
    for (const c of f.chains.filter((x) => !x.skipped)) {
      assert.deepStrictEqual(c.liquiditySamples, (got.get(c.chainId) ?? []).filter((s) => s.hour * HOUR >= b.inputs.window.startTs));
      assert.strictEqual(c.L.onChain, "5");
      assert.strictEqual(c.L.rule, "switch", "the switch window is valued at the v2 file's reading");
    }
    assert.deepStrictEqual(f.xdex, { atBuild: xdex, capReserve: null });
    assert.deepStrictEqual(verifyAny(f, epoch1), []);
    if (kit) assert.deepStrictEqual(kit.feedProblems(h1.feed, { now: h1.feed.asOf + 60 }).filter((p) => !/anomaly/i.test(p)), [], "the kit reads the new raw members");
  });

  await test("a chain whose reads fail is listed skipped, its cursor untouched, and the kit gives no quote on it", async () => {
    const r = rec();
    const failing = await assembleWeekSoFarV3(epoch1, { ...fixtureSources(r), finalHead: async (c) => { if (c.chainId === 8453) throw new Error("dead RPC"); return fixtureSources(r).finalHead(c); } }, chains, [epoch1], quiet);
    assert.deepStrictEqual(failing.skipped.map((x) => x.chainId), [8453]);
    assert(failing.feed.skipped.includes(8453));
    assert.deepStrictEqual(failing.feed.chains.find((c) => c.chainId === 8453), { chainId: 8453, name: "Base", portal: PORTAL, status: "skipped" });
    if (kit) assert.deepStrictEqual(kitView(kit, kit.supersetFeed(rawOfFeedV1(failing.feed), epoch1), failing.feed), failing.feed);
  });

  // ── 5. the workflow that serves it ────────────────────────────────────────────────────────────────
  const WF = path.join(REPO, ".github", "workflows");
  const wf = (f: string) => fs.readFileSync(path.join(WF, f), "utf8").replace(/\r\n/g, "\n");
  /** the dedented `run: |` block of the step named `name` */
  const runBlock = (text: string, name: string): string[] => {
    const lines = text.split("\n");
    const at = lines.findIndex((l) => l.trim() === `- name: ${name}`);
    assert(at >= 0, `step "${name}" not found`);
    const r = lines.findIndex((l, i) => i > at && /^\s+run: \|$/.test(l));
    assert(r > at, `step "${name}" has no run block`);
    const ind = lines[r].search(/\S/);
    const body: string[] = [];
    for (let i = r + 1; i < lines.length && (lines[i].trim() === "" || lines[i].search(/\S/) > ind); i++) body.push(lines[i]);
    while (body.length && body[body.length - 1].trim() === "") body.pop();
    const min = Math.min(...body.filter((l) => l.trim()).map((l) => l.search(/\S/)));
    return body.map((l) => l.slice(min));
  };

  await test("keeper.yml builds the site exactly as deploy-frontend.yml does (a feed deployment never ships another site)", () => {
    const keeper = wf("keeper.yml");
    const deploy = wf("deploy-frontend.yml");
    assert.deepStrictEqual(runBlock(keeper, "Build the site (as deploy-frontend.yml builds it)"), runBlock(deploy, "Build"));
    for (const t of [keeper, deploy]) assert(/working-directory: frontend\n\s+run: npm ci/.test(t), "npm ci in frontend");
    const env = (t: string, step: string) => t.slice(t.indexOf(`- name: ${step}`)).match(/env:\n\s+NODE_ENV: production/);
    assert(env(keeper, "Build the site (as deploy-frontend.yml builds it)") && env(deploy, "Build"), "NODE_ENV=production in both");
    // pinned to a commit with its version as a comment (r4-fix, review r4 finding 16: no workaround text in the pins)
    assert(/upload-pages-artifact@[0-9a-f]{40} # v3[.\d]*\n\s+with:\n\s+name: github-pages-feed\n\s+path: frontend\/dist/.test(keeper));
    assert(/deploy-pages@[0-9a-f]{40} # v4[.\d]*\n\s+with:\n\s+artifact_name: github-pages-feed/.test(keeper));
    assert(!/, i\.e\. actions\//.test(keeper), "no test workaround in the pin comments");
  });

  await test("keeper.yml's feed reads the same chains as the epoch build (oracle.yml) and serves the file where the site reads it", () => {
    const vars = (t: string) => [...t.matchAll(/^\s+((?:PORTAL|START)_[A-Z]+): \$\{\{ vars\.([A-Z_]+) \}\}$/gm)].map((m) => `${m[1]}=${m[2]}`).sort();
    const oracle = vars(wf("oracle.yml"));
    assert(oracle.length >= 10);
    assert.deepStrictEqual(vars(wf("keeper.yml")), oracle);
    assert(wf("keeper.yml").includes("frontend/dist/feed/week-so-far.json"));
    assert(wf("keeper.yml").includes("npm run --silent feed -- --gate-only"));
  });

  await test("health row: n/a before the switch; once live, a missing, stale or foreign feed warns (never red)", () => {
    const f = a1.feed;
    const newest = { epoch: 1, dataHash: epoch1.dataHash };
    const seen = { kind: f.kind, version: f.version, rules: f.rules, epoch: f.epoch, prevDataHash: f.prevEpoch.dataHash, asOf: f.asOf, readingsHour: f.readings.hour };
    const at = f.asOf + 600;
    assert.deepStrictEqual([feedVerdict("legacy", false, null, newest, at).state, feedVerdict("upgraded", false, null, newest, at).state], ["ok", "ok"]);
    assert.match(feedVerdict("upgraded", false, null, newest, at).detail, /v2 rules/);
    assert.strictEqual(feedVerdict("unknown", true, null, newest, at).state, "warn");
    assert.strictEqual(feedVerdict("upgraded", true, seen, newest, at).state, "ok");
    assert.strictEqual(feedVerdict("upgraded", true, null, newest, at).state, "warn");
    assert.strictEqual(feedVerdict("upgraded", true, seen, newest, f.asOf + 3 * HOUR).state, "warn", "stale");
    assert.strictEqual(feedVerdict("upgraded", true, seen, { epoch: 2, dataHash: "ab".repeat(32) }, at).state, "warn", "another window");
    assert.strictEqual(feedVerdict("upgraded", true, { ...seen, rules: 2 }, newest, at).state, "warn");
    assert.strictEqual(feedVerdict("upgraded", true, { ...seen, readingsHour: f.readings.hour! - 2 }, newest, at).state, "warn", "readings of an old hour");
    for (const s of [null, seen, { ...seen, asOf: 0 }]) assert.notStrictEqual(feedVerdict("upgraded", true, s, newest, at).state, "fail");
  });

  console.log(`week-so-far feed tests: ${passed} passed, ${failed} failed${skippedTests ? `, ${skippedTests} skipped (kit not installed)` : ""}${skippedNoVectors ? `, ${skippedNoVectors} skipped (kit vectors not in this tree)` : ""}`);
  if (failed) process.exit(1);
}

main().catch((e) => {
  console.error(e);
  process.exit(1);
});
